/* Release Relay: SLDS-style layout. Every class is prefixed rr- so Lightning's global styles can't collide. */
.rr-app { background: #f3f3f3; padding: 12px; border-radius: 4px; color: #181818; }
.rr-head { display: flex; align-items: center; gap: 12px; background: #fff; border: 1px solid #e5e5e5; border-radius: 4px 4px 0 0; padding: 12px 16px; }
.rr-head-icon { width: 32px; height: 32px; border-radius: 4px; background: #0176d3; display: flex; align-items: center; justify-content: center; }
.rr-head-kicker { font-size: 12px; color: #5c5c5c; }
.rr-head-title { font-size: 18px; font-weight: 700; }

.rr-card { background: #fff; border: 1px solid #e5e5e5; border-radius: 4px; display: flex; flex-direction: column; min-width: 0; }
.rr-card + .rr-card { margin-top: 12px; }
.rr-card-head { display: flex; justify-content: space-between; align-items: center; gap: 12px; padding: 12px 16px; border-bottom: 1px solid #e5e5e5; flex-wrap: wrap; }
.rr-card-title { font-size: 16px; font-weight: 700; margin: 0; }
.rr-card-body { padding: 16px; display: flex; flex-direction: column; gap: 16px; }
.rr-card-foot { display: flex; justify-content: flex-end; gap: 8px; padding: 12px 16px; border-top: 1px solid #e5e5e5; background: #fafaf9; }
.rr-label { font-size: 12px; color: #444; margin-bottom: 6px; display: block; }
.rr-weak { font-size: 12px; color: #5c5c5c; }
.rr-block { display: block; }
.rr-row { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.rr-spread { justify-content: space-between; }
.rr-grow { flex: 1 1 auto; min-width: 0; }
.rr-align-end { align-self: flex-end; }
.rr-two { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 16px; }
.rr-link { border: 0; background: none; padding: 0; color: #0b5cab; font: inherit; font-size: 13px; cursor: pointer; }
.rr-link:hover { text-decoration: underline; }
.rr-note { background: #f3f9ff; border-radius: 4px; padding: 12px; font-size: 13px; color: #1b3d5f; }
.rr-alert { color: #ba0517; font-size: 13px; }
.rr-success { background: #ebf7e6; color: #194e31; border-radius: 4px; padding: 12px; }
.rr-empty { padding: 12px 16px; color: #5c5c5c; }

/* path */
.rr-path { display: flex; flex-wrap: wrap; margin: 12px 0; }
.rr-path-step { flex: 1 1 160px; padding: 9px 16px; text-align: center; background: #e5e5e5; color: #444; border-left: 2px solid #f3f3f3; font-size: 13px; }
.rr-path-step:first-child { border-radius: 15px 0 0 15px; border-left: 0; }
.rr-path-step:last-child { border-radius: 0 15px 15px 0; }
.rr-path-step.done { background: #2e844a; color: #fff; }
.rr-path-step.current { background: #0176d3; color: #fff; font-weight: 700; }

/* segmented buttons */
.rr-seg { display: inline-flex; flex-wrap: wrap; border: 1px solid #c9c9c9; border-radius: 4px; overflow: hidden; }
.rr-seg-btn { border: 0; background: #fff; color: #0b5cab; padding: 8px 14px; font: inherit; font-size: 13px; cursor: pointer; }
.rr-seg-btn + .rr-seg-btn { border-left: 1px solid #c9c9c9; }
.rr-seg-btn.on { background: #0176d3; color: #fff; font-weight: 700; }
.rr-seg-btn:focus-visible, .rr-tile:focus-visible, .rr-type:focus-visible, .rr-stat:focus-visible, .rr-chip:focus-visible { outline: 2px solid #0176d3; outline-offset: 2px; }
.rr-seg-sm .rr-seg-btn { padding: 5px 12px; }

/* connect */
.rr-tiles { display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: 12px; }
.rr-tile { text-align: left; border: 1px solid #c9c9c9; border-radius: 4px; padding: 12px; background: #fff; display: flex; flex-direction: column; gap: 4px; font: inherit; cursor: pointer; }
.rr-tile.on { border: 2px solid #0176d3; background: #eef4ff; padding: 11px; }
.rr-tile-title { font-weight: 700; }
.rr-tile-add { border-style: dashed; align-items: center; justify-content: center; flex-direction: row; color: #0b5cab; }
.rr-route { display: grid; grid-template-columns: minmax(0, 1fr) 48px minmax(0, 1fr); gap: 12px; align-items: stretch; }
.rr-route-box { border: 1px solid #e5e5e5; border-radius: 4px; padding: 12px; display: flex; flex-direction: column; gap: 6px; }
.rr-route-source { background: #fafaf9; }
.rr-route-name { font-size: 15px; }
.rr-route-arrow { display: flex; align-items: center; justify-content: center; }
.rr-check { font-size: 12px; color: #5c5c5c; }
.rr-check.ok { color: #2e844a; }
.rr-check.bad { color: #ba0517; }
.rr-since { max-width: 220px; margin-top: 8px; }

/* select */
.rr-modebar { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; margin-bottom: 12px; }
.rr-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: 12px; margin-bottom: 12px; }
.rr-stat { text-align: left; background: #fff; border: 1px solid #e5e5e5; border-radius: 4px; padding: 10px 14px; display: flex; flex-direction: column; gap: 2px; font: inherit; cursor: pointer; }
.rr-stat-new { border-left: 4px solid #2e844a; }
.rr-stat-diff { border-left: 4px solid #dd7a01; }
.rr-stat-same { border-left: 4px solid #939393; }
.rr-stat-del { border-left: 4px solid #ba0517; }
.rr-stat.on { box-shadow: 0 0 0 2px #0176d3; }
.rr-stat-num { font-size: 22px; }
.rr-num-new { color: #2e844a; }
.rr-num-diff { color: #a96404; }
.rr-num-same { color: #5c5c5c; }
.rr-num-del { color: #ba0517; }
.rr-select { display: grid; grid-template-columns: 220px minmax(0, 1fr) 290px; gap: 12px; align-items: start; }
@media (max-width: 1100px) { .rr-select { grid-template-columns: 1fr; } }
.rr-select .rr-card + .rr-card { margin-top: 0; }
.rr-types-head { padding: 10px 12px; border-bottom: 1px solid #e5e5e5; display: flex; flex-direction: column; gap: 8px; }
.rr-types-group { padding: 8px 12px 2px; font-size: 11px; color: #5c5c5c; text-transform: uppercase; letter-spacing: .04em; }
.rr-type { display: flex; justify-content: space-between; align-items: center; gap: 8px; width: 100%; padding: 7px 12px; border: 0; border-left: 3px solid transparent; background: #fff; font: inherit; font-size: 13px; text-align: left; cursor: pointer; }
.rr-type:hover { background: #f3f3f3; }
.rr-type.on { background: #eef4ff; border-left-color: #0176d3; font-weight: 700; }
.rr-count { font-size: 12px; color: #444; background: #f3f3f3; border-radius: 10px; padding: 0 8px; }
.rr-types-add { padding: 10px 12px; border-top: 1px solid #e5e5e5; display: flex; flex-direction: column; gap: 6px; margin-top: 8px; }
.rr-toolbar { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; padding: 10px 12px; border-bottom: 1px solid #e5e5e5; }
.rr-since-pick { width: 150px; }
.rr-quick { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; padding: 8px 12px; border-bottom: 1px solid #e5e5e5; background: #fafaf9; }
.rr-chip { height: 28px; padding: 0 10px; border: 1px solid #c9c9c9; border-radius: 14px; background: #fff; color: #0b5cab; font: inherit; font-size: 12px; cursor: pointer; }
.rr-table-wrap { overflow: auto; max-height: 620px; }
.rr-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.rr-table th { position: sticky; top: 0; background: #fafaf9; text-align: left; font-size: 12px; font-weight: 600; color: #444; padding: 8px 10px; border-bottom: 1px solid #e5e5e5; z-index: 1; }
.rr-table td { padding: 8px 10px; border-bottom: 1px solid #e5e5e5; vertical-align: top; }
.rr-col-check { width: 28px; }
.rr-col-act { width: 40px; }
.rr-row-on td { background: #eef4ff; }
.rr-name { font-weight: 600; word-break: break-word; }
.rr-badge { display: inline-block; border-radius: 12px; padding: 1px 10px; font-size: 12px; font-weight: 600; white-space: nowrap; }
.rr-badge-new { background: #ebf7e6; color: #194e31; }
.rr-badge-diff { background: #fef1cd; color: #5c3a00; }
.rr-badge-same { background: #f3f3f3; color: #444; font-weight: 400; }
.rr-badge-exists { background: #eef4ff; color: #0b5cab; }
.rr-badge-del { background: #fef1ee; color: #8e030f; }
.rr-delta { font-family: monospace; font-size: 12px; margin-left: 6px; }
.rr-plus { color: #2e844a; }
.rr-minus { color: #ba0517; }
.rr-comparing { display: inline-flex; gap: 6px; align-items: center; color: #444; font-size: 12px; }
.rr-spin { width: 12px; height: 12px; border: 2px solid #c9c9c9; border-top-color: #0176d3; border-radius: 50%; animation: rr-spin 0.8s linear infinite; }
@keyframes rr-spin { to { transform: rotate(360deg); } }
.rr-preview-row td { background: #eef4ff; padding-top: 0; }
.rr-preview { border: 1px solid #d8e6fe; border-radius: 4px; background: #fff; overflow: auto; max-height: 320px; font-family: monospace; font-size: 12px; line-height: 1.7; }
.rr-preview-head { display: flex; justify-content: space-between; gap: 8px; padding: 6px 10px; background: #fafaf9; border-bottom: 1px solid #e5e5e5; font-family: -apple-system, 'Segoe UI', Roboto, Arial, sans-serif; font-size: 12px; color: #444; }
.rr-list-foot { display: flex; justify-content: space-between; align-items: center; gap: 8px; flex-wrap: wrap; padding: 10px 12px; }
.rr-basket { position: sticky; top: 8px; }
.rr-basket-head { display: flex; justify-content: space-between; align-items: center; padding: 12px 14px; border-bottom: 1px solid #e5e5e5; }
.rr-pill { border-radius: 12px; padding: 1px 10px; font-size: 12px; font-weight: 700; }
.rr-pill-brand { background: #0176d3; color: #fff; }
.rr-basket-badges { display: flex; gap: 6px; flex-wrap: wrap; padding: 10px 14px; border-bottom: 1px solid #e5e5e5; }
.rr-basket-item { display: flex; justify-content: space-between; align-items: center; gap: 8px; padding: 4px 14px; font-size: 13px; }
.rr-suggest { margin: 10px 14px; padding: 10px; background: #fef9ec; border: 1px solid #f3d38a; border-radius: 4px; display: flex; flex-direction: column; gap: 6px; font-size: 12px; color: #5c3a00; }
.rr-basket-section { padding: 10px 14px; border-top: 1px solid #e5e5e5; display: flex; flex-direction: column; gap: 6px; font-size: 13px; }
.rr-delete-confirm { margin: 0 14px 10px; padding: 8px 10px; border-radius: 4px; background: #fef1ee; }
.rr-basket-foot { padding: 12px 14px; border-top: 1px solid #e5e5e5; background: #fafaf9; display: flex; flex-direction: column; gap: 8px; }
.rr-block-btn { display: block; }

/* review */
.rr-review { flex-direction: row; flex-wrap: wrap; }
.rr-review-list { flex: 1 1 240px; max-width: 300px; border-right: 1px solid #e5e5e5; display: flex; flex-direction: column; }
.rr-review-progress { padding: 12px 16px; border-bottom: 1px solid #e5e5e5; display: flex; flex-direction: column; gap: 8px; }
.rr-bar { height: 6px; background: #e5e5e5; border-radius: 3px; }
.rr-bar-fill { height: 6px; background: #2e844a; border-radius: 3px; }
.rr-review-item { display: flex; gap: 10px; align-items: flex-start; width: 100%; text-align: left; border: 0; border-left: 3px solid transparent; border-bottom: 1px solid #e5e5e5; background: #fff; padding: 12px 13px; font: inherit; cursor: pointer; }
.rr-review-item.current { border-left-color: #0176d3; background: #eef4ff; }
.rr-review-text { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.rr-icon-ok { --slds-c-icon-color-foreground-default: #2e844a; }
.rr-review-main { flex: 999 1 560px; min-width: 0; display: flex; flex-direction: column; }
.rr-review-head { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; padding: 12px 16px; border-bottom: 1px solid #e5e5e5; }
.rr-file-tabs { display: flex; gap: 4px; padding: 0 16px; border-bottom: 1px solid #e5e5e5; flex-wrap: wrap; }
.rr-file-tab { border: 0; border-bottom: 3px solid transparent; background: #fff; padding: 10px 12px; font: inherit; font-size: 13px; color: #444; cursor: pointer; }
.rr-file-tab.on { border-bottom-color: #0176d3; font-weight: 700; color: #181818; }
.rr-sbs { display: grid; grid-template-columns: repeat(2, minmax(320px, 1fr)); font-family: monospace; font-size: 12px; line-height: 1.7; overflow: auto; max-height: 560px; }
.rr-sbs-head { padding: 6px 12px; background: #fafaf9; border-bottom: 1px solid #e5e5e5; font-family: -apple-system, 'Segoe UI', Roboto, Arial, sans-serif; font-weight: 600; color: #444; position: sticky; top: 0; }
.sbs-cell { padding: 0 12px; white-space: pre; min-height: 1.7em; }
.sbs-cell:nth-child(odd) { border-right: 1px solid #e5e5e5; }
.sbs-del { background: #ffebe9; }
.sbs-add { background: #e6ffec; }
.sbs-empty { background: #f6f6f6; }
.sbs-gap { color: #706e6b; font-style: italic; background: #fafaf9; }
.rr-no { display: inline-block; min-width: 2.5em; color: #939393; user-select: none; }
.rr-bar-card { flex-direction: row; justify-content: space-between; align-items: center; gap: 8px; flex-wrap: wrap; padding: 12px 16px; }

/* raise */
.rr-raise { display: grid; grid-template-columns: minmax(0, 2fr) minmax(260px, 1fr); gap: 12px; align-items: start; }
@media (max-width: 900px) { .rr-raise { grid-template-columns: 1fr; } }
.rr-raise .rr-card + .rr-card { margin-top: 0; }
.rr-dl { display: grid; grid-template-columns: max-content 1fr; gap: 8px 16px; padding: 16px; margin: 0; font-size: 13px; }
.rr-dl dt { color: #444; }
.rr-dl dd { margin: 0; word-break: break-word; }

/* connections */
.rr-conn-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); gap: 12px; }
.rr-conn-grid .rr-card + .rr-card { margin-top: 0; }

.diff {
    border: 1px solid #e5e5e5;
    border-radius: 0.25rem;
    overflow: hidden;
}

.diff-head {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    gap: 0.5rem;
    padding: 0.375rem 0.75rem;
    background: #f3f3f3;
    border-bottom: 1px solid #e5e5e5;
}

.diff-path {
    font-family: monospace;
    font-size: 0.75rem;
    word-break: break-all;
}

.diff-meta {
    font-size: 0.75rem;
    color: #706e6b;
}

.diff-body {
    margin: 0;
    max-height: 480px;
    overflow: auto;
    font-family: monospace;
    font-size: 0.75rem;
    line-height: 1.6;
    padding: 0.25rem 0;
}

.line {
    display: block;
    white-space: pre;
    padding: 0 0.75rem;
}

.line .sign {
    display: inline-block;
    width: 1.25rem;
    color: #706e6b;
}

.line.add {
    background: #ebf7e6;
    color: #194e31;
}

.line.del {
    background: #fef1ee;
    color: #8e030f;
}

.line.gap {
    color: #706e6b;
    font-style: italic;
    background: #fafaf9;
}

.desc textarea { min-height: 9rem; }
.file-list { max-height: 320px; overflow: auto; font-family: monospace; font-size: 0.75rem; line-height: 1.7; border: 1px solid #e5e5e5; border-radius: 0.25rem; padding: 0.5rem 0.75rem; }
.type-badge { display: inline-block; padding: 0.15rem 0.65rem; border-radius: 1rem; font-size: 0.75rem; font-weight: 700; }
.type-changes { background: #eef4ff; color: #0b5cab; }
.type-destructive { background: #fef1ee; color: #8e030f; }
.type-changes-and-destructive { background: #fef1cd; color: #8c4b02; }
.type-manual-pr { background: #f3f0ff; color: #5a1ba9; }
